    public sealed class StoryRunner
    {
        private readonly StorySceneDto _scene;
        private readonly Dictionary<string, bool> _flags = new Dictionary<string, bool>(StringComparer.Ordinal);
        private readonly Dictionary<string, int> _labels = new Dictionary<string, int>(StringComparer.Ordinal);
        private readonly List<string> _choices = new List<string>();
        private readonly List<StoryEvent> _history = new List<StoryEvent>();

        private int _pc;
        private int? _currentBlockingPc;
        private StoryCommandDto _pendingChoice;
        private bool _ended;
        private int _controlSteps;

        public RestoredSceneState Restored { get; }
        public IReadOnlyList<StoryEvent> History => _history;
        public bool Finished => _ended;

        public StoryRunner(StorySceneDto scene, StorySaveDto save = null)
        {
            _scene = scene ?? throw new ArgumentNullException(nameof(scene));
            Restored = new RestoredSceneState { locationId = scene.location_id ?? "" };

            var cmds = scene.commands ?? Array.Empty<StoryCommandDto>();
            for (int i = 0; i < cmds.Length; i++)
            {
                if (cmds[i] != null && cmds[i].op == "label" && !string.IsNullOrEmpty(cmds[i].name))
                {
                    _labels[cmds[i].name] = i;
                }
            }

            if (save != null)
            {
                if (save.sceneId != scene.scene_id)
                {
                    throw new InvalidOperationException("Save belongs to another scene.");
                }
                _pc = Math.Min(Math.Max(0, save.index), cmds.Length);
                if (save.choices != null) _choices.AddRange(save.choices);
                if (save.flags != null)
                {
                    foreach (var kv in save.flags)
                    {
                        _flags[kv.Key] = kv.Value;
                    }
                }
                ReconstructUntil(_pc, _choices);
            }
        }

        public StoryEvent Next()
        {
            if (_ended) return null;
            if (_pendingChoice != null)
            {
                throw new InvalidOperationException("A choice is pending; call Choose() first.");
            }

            var cmds = _scene.commands ?? Array.Empty<StoryCommandDto>();
            int maxBudget = Math.Max(16, cmds.Length * 4);

            for (;;)
            {
                if (++_controlSteps > maxBudget)
                {
                    throw new InvalidOperationException("Story control flow exceeded its finite step budget.");
                }

                int cmdPc = _pc;
                if (cmdPc < 0 || cmdPc >= cmds.Length || cmds[cmdPc] == null)
                {
                    _ended = true;
                    _currentBlockingPc = null;
                    return new StoryEvent { type = "end" };
                }

                var cmd = cmds[cmdPc];
                _pc++;

                switch (cmd.op)
                {
                    case "set_flag":
                        _flags[cmd.flag] = cmd.value;
                        continue;
                    case "branch":
                        bool curVal = _flags.TryGetValue(cmd.flag, out bool fv) && fv;
                        if (curVal == cmd.equals)
                        {
                            _pc = MustLabel(cmd.@goto);
                        }
                        continue;
                    case "label":
                        continue;
                    case "goto":
                        _pc = MustLabel(cmd.label);
                        continue;
                    case "voice":
                    case "sound":
                    case "video":
                    case "layer":
                    case "remove_layer":
                    case "animate":
                    case "camera":
                    case "mask":
                    case "panel":
                        if (cmd.op == "video" || cmd.op == "panel" || (cmd.op == "animate" && cmd.wait && cmd.seconds > 0f))
                        {
                            _controlSteps = 0;
                            _currentBlockingPc = cmdPc;
                        }
                        else
                        {
                            _currentBlockingPc = null;
                        }
                        return new StoryEvent { type = "presentation", command = cmd };
                    case "background":
                        _currentBlockingPc = null;
                        Restored.locationId = cmd.location_id;
                        return new StoryEvent { type = "background", locationId = cmd.location_id };
                    case "music":
                        _currentBlockingPc = null;
                        Restored.musicCueId = cmd.cue_id;
                        return new StoryEvent { type = "music", cueId = cmd.cue_id };
                    case "fade":
                        _currentBlockingPc = null;
                        return new StoryEvent { type = "fade", direction = cmd.direction, seconds = cmd.seconds };
                    case "show":
                        _currentBlockingPc = null;
                        Restored.actors[cmd.character] = new StoryActorState { side = cmd.side, emotion = "composed" };
                        return new StoryEvent { type = "show", character = cmd.character, side = cmd.side };
                    case "hide":
                        _currentBlockingPc = null;
                        Restored.actors.Remove(cmd.character);
                        return new StoryEvent { type = "hide", character = cmd.character };
                    case "flash":
                        _currentBlockingPc = null;
                        return new StoryEvent { type = "flash", seconds = cmd.seconds };
                    case "shake":
                        _currentBlockingPc = null;
                        return new StoryEvent { type = "shake", seconds = cmd.seconds, intensity = cmd.intensity };
                    case "wait":
                        if (cmd.seconds > 0f) _controlSteps = 0;
                        _currentBlockingPc = cmdPc;
                        return new StoryEvent { type = "wait", seconds = cmd.seconds };
                    case "checkpoint":
                        _currentBlockingPc = null;
                        return new StoryEvent { type = "checkpoint", checkpointId = cmd.checkpoint_id };
                    case "say":
                    {
                        _controlSteps = 0;
                        _currentBlockingPc = cmdPc;
                        Restored.prevSpeaker = cmd.speaker;
                        if (Restored.actors.TryGetValue(cmd.speaker, out var actor) && !string.IsNullOrEmpty(cmd.emotion))
                        {
                            actor.emotion = cmd.emotion;
                        }
                        var ev = new StoryEvent
                        {
                            type = "line",
                            lineId = cmd.line_id,
                            speaker = cmd.speaker,
                            speakerDisplay = cmd.speaker_display,
                            text = cmd.text,
                            emotion = cmd.emotion,
                            holdSeconds = cmd.hold_seconds
                        };
                        _history.Add(ev);
                        return ev;
                    }
                    case "narrate":
                    {
                        _controlSteps = 0;
                        _currentBlockingPc = cmdPc;
                        Restored.prevSpeaker = "narration";
                        var ev = new StoryEvent
                        {
                            type = "line",
                            lineId = cmd.line_id,
                            speaker = "narration",
                            speakerDisplay = "",
                            text = cmd.text,
                            holdSeconds = cmd.hold_seconds
                        };
                        _history.Add(ev);
                        return ev;
                    }
                    case "choice":
                        _controlSteps = 0;
                        _currentBlockingPc = cmdPc;
                        _pendingChoice = cmd;
                        return new StoryEvent
                        {
                            type = "choice",
                            prompt = cmd.prompt,
                            options = cmd.options ?? Array.Empty<StoryChoiceOptionDto>()
                        };
                    case "end":
                        _ended = true;
                        _currentBlockingPc = null;
                        return new StoryEvent { type = "end" };
                }
            }
        }

        public void Choose(string optionId)
        {
            if (_pendingChoice == null)
            {
                throw new InvalidOperationException("No choice is pending.");
            }
            StoryChoiceOptionDto matched = null;
            var opts = _pendingChoice.options ?? Array.Empty<StoryChoiceOptionDto>();
            for (int i = 0; i < opts.Length; i++)
            {
                if (opts[i] != null && opts[i].id == optionId)
                {
                    matched = opts[i];
                    break;
                }
            }
            if (matched == null)
            {
                throw new InvalidOperationException($"Unknown option '{optionId}'.");
            }

            _choices.Add(optionId);
            _pendingChoice = null;
            _currentBlockingPc = null;
            _pc = MustLabel(matched.@goto);
        }

        public StorySaveDto SaveAtCurrentEvent()
        {
            return new StorySaveDto
            {
                sceneId = _scene.scene_id,
                index = _currentBlockingPc ?? _pc,
                choices = _choices.ToArray(),
                flags = new Dictionary<string, bool>(_flags, StringComparer.Ordinal)
            };
        }

        private void ReconstructUntil(int targetPc, List<string> savedChoices)
        {
            var cmds = _scene.commands ?? Array.Empty<StoryCommandDto>();
            var walkFlags = new Dictionary<string, bool>(StringComparer.Ordinal);
            int cursor = 0;
            int choiceIdx = 0;
            int steps = 0;
            int maxSteps = Math.Max(16, cmds.Length * 4);

            while (cursor < cmds.Length && cursor != targetPc && steps++ < maxSteps)
            {
                var cmd = cmds[cursor++];
                if (cmd == null) continue;
                switch (cmd.op)
                {
                    case "set_flag":
                        walkFlags[cmd.flag] = cmd.value;
                        break;
                    case "branch":
                        bool val = (walkFlags.TryGetValue(cmd.flag, out bool wf) ? wf : (_flags.TryGetValue(cmd.flag, out bool sf) && sf));
                        if (val == cmd.equals && _labels.TryGetValue(cmd.@goto, out int bDst))
                        {
                            cursor = bDst;
                        }
                        break;
                    case "goto":
                        if (_labels.TryGetValue(cmd.label, out int gDst))
                        {
                            cursor = gDst;
                        }
                        break;
                    case "choice":
                        string chosen = choiceIdx < savedChoices.Count ? savedChoices[choiceIdx++] : null;
                        if (chosen != null && cmd.options != null)
                        {
                            for (int i = 0; i < cmd.options.Length; i++)
                            {
                                if (cmd.options[i] != null && cmd.options[i].id == chosen && _labels.TryGetValue(cmd.options[i].@goto, out int cDst))
                                {
                                    cursor = cDst;
                                    break;
                                }
                            }
                        }
                        break;
                    case "background":
                        Restored.locationId = cmd.location_id;
                        break;
                    case "music":
                        Restored.musicCueId = cmd.cue_id;
                        break;
                    case "show":
                        Restored.actors[cmd.character] = new StoryActorState { side = cmd.side, emotion = "composed" };
                        break;
                    case "hide":
                        Restored.actors.Remove(cmd.character);
                        break;
                }
            }
        }

        private int MustLabel(string name)
        {
            if (_labels.TryGetValue(name ?? "", out int idx)) return idx;
            throw new InvalidOperationException($"Unknown label '{name}'.");
        }
    }
